const request = $json.body ?? $json;
for (const field of ['journey_id', 'customer_id', 'customer_goal', 'requested_amount']) { if (request[field] === undefined || request[field] === null || request[field] === '') throw new Error(`Missing required field: ${field}`); }
if (!Number.isFinite(Number(request.requested_amount)) || Number(request.requested_amount) <= 0) throw new Error('requested_amount must be a positive number');
return [{ json: { journey_id: request.journey_id, customer_id: request.customer_id, customer_goal: request.customer_goal, requested_amount: Number(request.requested_amount) } }];

const journey = $node['Validate Request'].json;
const crm = $node['Get Simulated CRM Context'].json;
const financial = $node['Get Simulated Financial Context'].json;
const credit = $node['Get Simulated Credit Context'].json;
return [{ json: { ...journey, crm, financial, credit, model_features: { revenue: financial.annual_revenue, dti_n: financial.dti_n, loan_amnt: journey.requested_amount, fico_n: credit.fico_n, emp_length: credit.emp_length, purpose: financial.purpose, home_ownership_n: credit.home_ownership_n } } }];

// SHAP is already computed by the existing backend inference service.
// This node makes that explanatory context explicit for the journey.
return [{ json: { ...$json, shap_source: 'EXISTING_BACKEND_INFERENCE', is_simulated_journey: true } }];

const policy = $node['Evaluate Policy'].json;
const recovery = $json;
const journey = $node['Build Model Context'].json;
return [{ json: { journey_id: journey.journey_id, customer_goal: journey.customer_goal, requested_amount: journey.requested_amount, risk_signal: $node['Get SHAP Explanation'].json, policy_decision: policy, goal_recovery: recovery, next_action: recovery.available_paths.length ? 'Present prototype recovery paths; no approval is implied.' : 'Follow the governed policy result.', audit: { policy_version: policy.policy_version, recovery_version: recovery.recovery_version, simulated: true } } }];
